/** Where the app lives; everything cached is under here. */
const SCOPE = new URL(self.registration.scope).pathname;
const SHELL = `${SCOPE}index.html`;

self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CACHE);
      // One request at a time rather than cache.addAll, which rejects the whole
      // batch if any single file fails. A missing font should cost the font,
      // not the entire offline build.
      const results = await Promise.allSettled(
        PRECACHE.map(async (path) => {
          const url = SCOPE + path;
          // 'reload' so a half-filled HTTP cache from a previous visit cannot
          // seed the precache with stale bytes.
          const response = await fetch(url, { cache: 'reload' });
          if (!response.ok) throw new Error(`${response.status} ${url}`);
          await cache.put(url, response);
        })
      );
      const failed = results.filter((r) => r.status === 'rejected');
      if (failed.length) {
        console.warn(
          `[sw] ${failed.length} of ${PRECACHE.length} files did not precache`,
          failed.slice(0, 5).map((r) => r.reason?.message)
        );
      }
      // Take over immediately. Without this a deploy sits behind every open tab
      // being closed, and on a phone a tab is rarely closed at all.
      await self.skipWaiting();
    })()
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      // Each deploy gets its own cache name, so the old one is dropped whole
      // rather than being selectively invalidated - simpler, and there is no
      // way for a stale file to survive by being missed.
      const names = await caches.keys();
      await Promise.all(
        names
          .filter((name) => name.startsWith('french-app-') && name !== CACHE)
          .map((name) => caches.delete(name))
      );
      await self.clients.claim();
    })()
  );
});

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;
  // Leave the other app on this domain entirely alone. FE Prep is served from
  // the same origin under a different path and has its own worker; answering
  // for it would be both wrong and hard to debug.
  if (!url.pathname.startsWith(SCOPE)) return;

  // A navigation is a request for a screen, and the screens are client-side
  // routes - /french-app/reading/1 is not a file. So every navigation is
  // answered with the app shell and the router works out the rest. This is the
  // same reason 404.html is a copy of index.html for the uninstalled case.
  if (request.mode === 'navigate') {
    event.respondWith(
      (async () =>
        (await caches.match(SHELL)) ||
        (await fetch(request).catch(() => caches.match(SHELL))))()
    );
    return;
  }

  event.respondWith(
    (async () => {
      const hit = await caches.match(request, { ignoreSearch: true });
      if (hit) return hit;
      try {
        const response = await fetch(request);
        // Only same-origin successes are worth keeping. An opaque cross-origin
        // response cannot be inspected, so caching one would store a failure
        // indistinguishable from a success.
        if (response.ok && response.type === 'basic') {
          const cache = await caches.open(CACHE);
          cache.put(request, response.clone());
        }
        return response;
      } catch (error) {
        // Offline and not precached. Nothing useful to answer with, so let the
        // caller see the failure rather than a misleading empty 200.
        throw error;
      }
    })()
  );
});
